#!/usr/bin/env bash
ssh -o BatchMode=yes host-machine 'export XDG_RUNTIME_DIR=/run/user/1000; export WAYLAND_DISPLAY=wayland-0; export DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus; export XDG_SESSION_TYPE=wayland; pkill -9 -f "/home/trajan/Applications/T3-Code-fork|/tmp/.mount_T3|t3code" || true; kdotool set_desktop 1 >/dev/null 2>&1 || true; nohup /home/trajan/Applications/T3-Code-fork-0.0.17-x86_64.AppImage --no-sandbox --ozone-platform=wayland >/tmp/t3-place.log 2>&1 & sleep 8; ID=$(kdotool search --class "place-companion" 2>/dev/null | head -1); echo ID=$ID; if [ -n "$ID" ]; then kdotool windowactivate "$ID" >/dev/null 2>&1 || true; kdotool windowsize "$ID" 900 700 >/dev/null 2>&1 || true; kdotool windowmove "$ID" 2750 320 >/dev/null 2>&1 || true; fi; sleep 1; spectacle -b -n -f -o /tmp/t3-right-monitor-center.png >/dev/null 2>&1 || true; ls -lh /tmp/t3-right-monitor-center.png 2>/dev/null || true; sed -n "1,80p" /tmp/t3-place.log || true'